import{_ as e,o as r,c as a,a5 as n}from"./chunks/framework.BZzouRtU.js";const o="/study/images/hardware/instruction-execution.svg",g=JSON.parse('{"title":"CPUの命令実行 — レジスタとプログラムカウンター","description":"","frontmatter":{"title":"CPUの命令実行 — レジスタとプログラムカウンター","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"hardware","summary":"CPUが命令を取得して意味を解釈し、レジスタやメモリの値を更新する流れを追う。命令セット、クロック、コア、論理プロセッサーも説明する。","aliases":["CPU","命令","機械語","ISA","命令セット","レジスタ","プログラムカウンター","PC","ロード","ストア","クロック","GHz","コア","SMT","論理プロセッサー"],"verification":"RISC-Vの命令セット仕様とIntelのクロック・SMT・命令完了の資料に照合（2026-11-07）"}},"headers":[],"relativePath":"hardware/cpu/instruction-execution.md","filePath":"hardware/cpu/instruction-execution.md"}'),s={name:"hardware/cpu/instruction-execution.md"};function d(i,t,c,h,l,p){return r(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="cpuの命令実行-—-レジスタとプログラムカウンター" tabindex="-1">CPUの命令実行 — レジスタとプログラムカウンター <a class="header-anchor" href="#cpuの命令実行-—-レジスタとプログラムカウンター" aria-label="Permalink to &quot;CPUの命令実行 — レジスタとプログラムカウンター&quot;">​</a></h1><p>CPUはプログラムの<strong>命令</strong>を読み、指定された計算やデータの移動を行います。「値を3増やす」という短い処理も、値を取り出し、3を足して、結果を保存する操作に分けられます。小さな架空のCPUを使い、この流れを追います。<a href="/study/hardware/computer-components.html">コンピュータの部品と役割</a></p><h2 id="命令と命令セット" tabindex="-1">命令と命令セット <a class="header-anchor" href="#命令と命令セット" aria-label="Permalink to &quot;命令と命令セット&quot;">​</a></h2><p>命令には「どの操作をするか」と「どの値や場所を使うか」が含まれます。CPUが解釈するバイトの並びを<strong>機械語</strong>、命令を人が読める記号で書く表現を<strong>アセンブリ言語</strong>と呼びます。例えば加算の命令には、計算元と結果の保存先を示す情報が必要です。<a href="https://docs.riscv.org/reference/isa/v20260120/unpriv/rv32.html" target="_blank" rel="noreferrer">RISC-Vの命令形式と演算</a></p><p>CPUにどの命令があり、各命令がどんな結果を生むかを定める仕様が**命令セットアーキテクチャー（ISA）**です。x86-64、AArch64、RISC-Vなどでは、使える命令やその符号化が異なります。ソースコードから実行ファイルを作るとき、コンパイラーは対象の命令セットに合うコードを生成します。<a href="https://docs.riscv.org/reference/isa/v20260120/unpriv/rv32.html" target="_blank" rel="noreferrer">RISC-Vの基本命令セット</a> · <a href="/study/runtime/cpp-internals/build-pipeline-journey.html">コンパイルから実行まで</a></p><h2 id="値を一時的に置くレジスタ" tabindex="-1">値を一時的に置くレジスタ <a class="header-anchor" href="#値を一時的に置くレジスタ" aria-label="Permalink to &quot;値を一時的に置くレジスタ&quot;">​</a></h2><p><strong>レジスタ</strong>はCPUが命令の処理に使う、名前や番号で指定できる小さな記憶場所です。計算する値、アドレス、計算結果などを持ちます。普通のメモリからレジスタへ値を読む操作を<strong>ロード</strong>、レジスタからメモリへ値を書く操作を<strong>ストア</strong>と呼びます。RISC-Vの整数演算では、加算などの入力と出力にレジスタを使います。<a href="https://docs.riscv.org/reference/isa/v20260120/unpriv/rv32.html" target="_blank" rel="noreferrer">RISC-Vのレジスタとロード・ストア命令</a></p><p>次の命令の位置を追うためには、<strong>プログラムカウンター（PC）<strong>と呼ぶ状態も使います。RISC-VのPCは現在の命令のアドレスを持ち、順に進むときや分岐するときの規則が仕様で決まっています。x86系では</strong>命令ポインター</strong>という名前も使われます。<a href="https://docs.riscv.org/reference/isa/v20260120/unpriv/rv32.html" target="_blank" rel="noreferrer">RISC-VのPCと制御の移動</a> · <a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intelのソフトウェア開発者向けマニュアル</a></p><h2 id="_5を読み、3を足し、8を書き戻す" tabindex="-1">5を読み、3を足し、8を書き戻す <a class="header-anchor" href="#_5を読み、3を足し、8を書き戻す" aria-label="Permalink to &quot;5を読み、3を足し、8を書き戻す&quot;">​</a></h2><p>以下は説明用の架空の命令です。命令の位置を<code>0</code>、<code>1</code>、<code>2</code>と番号で表し、PCはこれから実行する番号を持つものとします。<code>M[100]</code>は「メモリの100番地にある値」、<code>R0</code>は一つのレジスタです。最初の<code>M[100]</code>は<code>5</code>です。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0  LOAD  R0, M[100]    # メモリからR0へ読む</span></span>
<span class="line"><span>1  ADD   R0, 3         # R0に3を足す</span></span>
<span class="line"><span>2  STORE M[100], R0    # R0をメモリへ書く</span></span></code></pre></div><table tabindex="0"><thead><tr><th>実行する番号</th><th>操作</th><th>実行後のR0</th><th>実行後のM[100]</th><th>次のPC</th></tr></thead><tbody><tr><td>0</td><td><code>LOAD</code>で5を読む</td><td>5</td><td>5</td><td>1</td></tr><tr><td>1</td><td><code>ADD</code>で3を足す</td><td>8</td><td>5</td><td>2</td></tr><tr><td>2</td><td><code>STORE</code>で8を書く</td><td>8</td><td>8</td><td>3</td></tr></tbody></table><figure class="study-figure"><img src="`+o+'" alt="架空のCPUで、PCが0のときメモリの5をレジスタR0へロードする。PCが1でR0に3を足して8にし、PCが2でメモリへ8をストアする。命令ごとに取得、解読、実行を考えられる。" width="760" height="420" loading="lazy"><figcaption>計算直後はR0だけが8になり、ストアした時点でメモリ側の値も8になります。<a href="/study/images/hardware/instruction-execution.svg" target="_blank" rel="noopener noreferrer">命令実行の図を拡大</a></figcaption></figure><p>この例には繰り返しを入れていません。条件によって次の命令の位置を変える<strong>分岐</strong>や、別の処理へ移って戻る<strong>関数呼び出し</strong>を組み合わせると、ゲームの条件判断や繰り返しを表せます。<a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出しとCPU</a></p><h2 id="取得・解読・実行で考える" tabindex="-1">取得・解読・実行で考える <a class="header-anchor" href="#取得・解読・実行で考える" aria-label="Permalink to &quot;取得・解読・実行で考える&quot;">​</a></h2><p>命令を追うときは、まずPCが示す位置から命令を<strong>取得</strong>し、操作と対象を<strong>解読</strong>し、計算や読み書きを<strong>実行</strong>すると考えます。メモリを使う命令では、CPUのキャッシュやメモリの仕組みも働きます。<a href="/study/hardware/memory/ram-cache-and-storage.html">RAM・キャッシュ・ストレージ</a></p><p>実際の高性能CPUは、複数の命令の処理を重ね、準備が整った操作を先に進める<strong>アウトオブオーダー実行</strong>などを使います。完了した命令の結果をプログラムが観測する状態へ確定する段階を<strong>リタイア</strong>と呼びます。Intelの該当するCPUでは、結果をプログラム順に確定する仕組みがあります。<a href="https://www.intel.com/content/www/us/en/docs/vtune-profiler/user-guide/2026-0/instructions-retired-event.html" target="_blank" rel="noreferrer">Intelの命令のリタイア</a> · <a href="/study/runtime/cpp-internals/cache-branch-simd.html">キャッシュ・分岐・SIMDの詳細</a></p><h2 id="ghzは命令数をそのまま表すか" tabindex="-1">GHzは命令数をそのまま表すか <a class="header-anchor" href="#ghzは命令数をそのまま表すか" aria-label="Permalink to &quot;GHzは命令数をそのまま表すか&quot;">​</a></h2><p><strong>クロック周波数</strong>は、CPU内部の動作の基準となる周期が1秒間に何回あるかを表します。<code>1 GHz</code>は1秒間に10億周期です。一つの命令の処理が複数周期にまたがる場合も、複数の命令を重ねて進める場合もあるため、<code>3 GHz</code>という表示だけから「毎秒30億命令」とは計算できません。同じ処理を終えるまでの時間には、命令の構成、メモリ待ち、CPUの実装なども関わります。<a href="https://www.intel.com/content/www/us/en/gaming/resources/cpu-clock-speed.html" target="_blank" rel="noreferrer">Intelのクロック周波数の解説</a></p><h2 id="コアと論理プロセッサー" tabindex="-1">コアと論理プロセッサー <a class="header-anchor" href="#コアと論理プロセッサー" aria-label="Permalink to &quot;コアと論理プロセッサー&quot;">​</a></h2><p><strong>コア</strong>はCPU内で命令の実行を進める処理のまとまりです。複数のコアを持つCPUでは、複数の命令列を並行して実行できます。<strong>SMT</strong>は、一つのコアで複数のハードウェアスレッドの状態を持ち、実行資源を共有して利用する方式です。IntelのHyper-Threadingもその一例です。OSから見える実行先を<strong>論理プロセッサー</strong>と呼びます。<a href="https://www.intel.com/content/www/us/en/gaming/resources/hyper-threading.html" target="_blank" rel="noreferrer">IntelのHyper-Threadingの解説</a></p><p>例えば4コア・8論理プロセッサーの構成でも、すべての計算用回路が8コア分になるわけではありません。OSが各スレッドをどの実行先へ割り当てるか、同時に進められる仕事がどれだけあるかによって、処理時間が変わります。<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Microsoftのスレッドとスケジューリング</a></p>',22)])])}const m=e(s,[["render",d]]);export{g as __pageData,m as default};
